{
  "id": "V038",
  "checks": [
    {
      "field": "purpose",
      "score": 2,
      "reason": "청구서 검토 시간을 줄이려는 목적이 BUSINESS 뷰에 보존되었습니다."
    },
    {
      "field": "action",
      "score": 2,
      "reason": "청구 항목 금액과 합의된 요율을 비교하고 의심 부분 및 근거를 기록합니다."
    },
    {
      "field": "object",
      "score": 2,
      "reason": "화물 청구서의 항목별 금액과 합의된 요율이 보존되었습니다."
    },
    {
      "field": "input",
      "score": 2,
      "reason": "TECHNICAL 뷰가 화물 청구서의 항목별 금액과 요율을 입력으로 명시합니다."
    },
    {
      "field": "output",
      "score": 2,
      "reason": "의심되는 과다 청구 부분과 비교 근거를 검토 목록으로 남깁니다."
    },
    {
      "field": "constraints",
      "score": 2,
      "reason": "청구서 자동 수정과 대금 지급을 하지 않으며, 담당자 확인 후 처리한다는 제약이 보존되었습니다."
    },
    {
      "field": "no_added_functions",
      "score": 2,
      "reason": "원문에 없는 기능이 추가되지 않았습니다."
    },
    {
      "field": "roles",
      "score": 2,
      "reason": "운송비 검토 담당자의 확인 및 처리 역할이 보존되었습니다."
    }
  ],
  "issues": [],
  "permission_interpretation": "자동 수정이나 지급은 하지 않고, 담당자가 확인한 뒤 처리합니다. 담당자가 매번 특정 조치를 모두 수행한다고 단정하지 않습니다."
}
